/// Finds `key` given its already-computed home bucket.
fn find_from_home<Q>(&self, home: usize, key: &Q) -> Option<Position>
where
    K: Borrow<Q>,
    Q: Hash + Eq + ?Sized,
{
    let bucket = &self.slots[home];
    for offset in NeighborhoodOffsets::new(bucket) {
        let index = home + offset;
        if let Some((k, _)) = self.slots[index].entry() {
            if k.borrow() == key {
                return Some(Position::Slot(index));
            }
        }
    }
    if bucket.has_overflow() {
        for (i, (k, _)) in self.overflow.iter().enumerate() {
            if k.borrow() == key {
                return Some(Position::Overflow(i));
            }
        }
    }
    None
